def eval_rpn(tokens):
    stack = []
    operators = set(['+', '-', '*', '/'])

    for token in tokens:
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            stack.append(int(token))
        elif token in operators:
            if len(stack) < 2:
                raise ValueError("Not enough operands for operator")
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("Division by zero")
                stack.append(int(a / b))
        else:
            raise ValueError("Unknown token")

    if len(stack) != 1:
        raise ValueError("More than one value left at the end")

    return stack[0]

