class ParkingLot:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity < 1:
            raise ValueError("Capacity must be an integer >= 1")
        self.capacity = capacity
        self.parked_cars = {}

    def park(self, plate):
        if len(self.parked_cars) == self.capacity:
            raise ValueError("Parking lot is full")
        if plate in self.parked_cars:
            raise ValueError("Car with plate {} is already parked".format(plate))
        for spot in range(1, self.capacity + 1):
            if spot not in self.parked_cars:
                self.parked_cars[spot] = plate
                return spot

    def leave(self, plate):
        if plate not in self.parked_cars:
            raise KeyError("Car with plate {} is not parked".format(plate))
        spot = self.parked_cars.pop(plate)
        return spot

    def spot_of(self, plate):
        return self.parked_cars.get(plate)

    def free(self):
        return self.capacity - len(self.parked_cars)

